private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    long[] sum = new long[n + 1];
    for (int i = 0; i < n; i++) {
        sum[i + 1] = sum[i] + bounds.get(i);
    }
    List<Integer> suffixSum = IntStream.rangeClosed(1, n).map(i -> sum[i]).collect(Collectors.toList());
    return new Pair<>(suffixSum, sum[n]);
}

