private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if(vertices.isEmpty() || vertices.size() == 1){
        return true;
    }

    for(V vertex: vertices){
        Set<E> neighbors = graph.outgoingEdgesOf(vertex);
        if(neighbors == null || neighbors.size() < vertices.size()){
            return false;
        }
        for(V neighbor: vertices){
            if(!neighbors.contains(graph.outgoingEdge(vertex, neighbor))){
                return false;
            }
        }
    }

    return true;
}

